95		switch {
96		case a.switchingTo != "":
97			return a.renderContextSwitchingOverlay()
98		case a.showHelp:
99			return a.renderHelpOverlay()
100		case a.showContextList:
101			return a.renderContextListOverlay()
102		}
103		return ""
104	}
105	
106	// renderBody fills the viewport with the active view's content, padded to the
107	// full inner width so no line shows the terminal's own background (Rule 115).
108	func (a *App) renderBody() string {
109		content := "View not found: " + string(a.currentView)
110		if view, ok := a.views[a.currentView]; ok {
111			content = view.Render()
112		}
113	
114		innerWidth := a.viewport.Width() - 2 // -2 for the borders
115		if a.frameless() {
116			innerWidth = a.viewport.Width()
117		}
118		a.viewport.SetContent(lipgloss.NewStyle().
119			Background(theme.ColorBackground).
120			Foreground(theme.ColorText).
121			Width(innerWidth).
122			Render(content))
123	
124		body := a.viewport.View()
125	
126		// Rule 136: with a filter bar below it, the viewport's bottom corners become
127		// T-junctions so the two form one closed rectangle.
128		if view, ok := a.views[a.currentView]; ok {
129			if fbv, ok := view.(FilterBarView); ok && fbv.FilterBarVisible() {
130				body = replaceViewportBottomCorners(body)
131			}
132		}
133		return body
134	}
135	
136	// renderTitleLine draws the viewport's top border carrying the view's title —
137	// or, for a frameless view, a titled rule with no corners: GetTitle() keeps a
138	// reader oriented where a top border would draw the top of a nonexistent box.
139	func (a *App) renderTitleLine() string {
140		title := ""
141		if view, ok := a.views[a.currentView]; ok {
142			if hv, implements := view.(HeaderView); implements {
143				title = hv.GetTitle()
144			}
145		}
146		if a.frameless() {
147			return theme.RenderTitledRule(title, a.width)
148		}
149		return theme.RenderBorderTitleTrail(title, a.frameTrail(title), a.width)
150	}
151	
152	// frameTrail asks the active view for its border trail, within the budget the
153	// theme leaves after title. It returns "" when there is no room, the view has
154	// no trail, or the trail is wider than its budget.
155	func (a *App) frameTrail(title string) string {
156		view, ok := a.views[a.currentView]
157		if !ok {
158			return ""
159		}
160		tv, ok := view.(FrameTrailView)
161		if !ok {
162			return ""
163		}
164		budget := theme.BorderTrailBudget(title, a.width)
165		if budget <= 0 {
166			return ""
167		}
168		trail := tv.FrameTrail(budget)
169		if lipgloss.Width(trail) > budget {
170			return ""
171		}
172		return trail
173	}
174	
175	// frameless reports whether the active view draws its own frames (see
176	// FramelessView). The default is framed.
177	func (a *App) frameless() bool {
178		view, ok := a.views[a.currentView]
179		if !ok {
180			return false
181		}
182		fv, implements := view.(FramelessView)
183		return implements && fv.Frameless()
184	}
185	
186	// renderViewFooter returns the active view's footer, or "" when it has none.
187	func (a *App) renderViewFooter() string {
188		if view, ok := a.views[a.currentView]; ok {
189			if fv, ok := view.(FooterView); ok {
190				return fv.RenderFooter(a.width)
191			}
192		}
193		return ""
194	}
195	
196	// replaceViewportBottomCorners turns the viewport's bottom └ and ┘ into the
197	// T-junctions ├ and ┤, so the filter bar rendered below it in the footer joins
198	// the border into one closed rectangle instead of two stacked boxes.
199	func replaceViewportBottomCorners(body string) string {
200		lastNewline := strings.LastIndex(body, "\n")
201		if lastNewline == -1 {
202			return body
203		}
204		lastLine := body[lastNewline+1:]
205		lastLine = strings.Replace(lastLine, "└", "├", 1)
206		lastLine = strings.Replace(lastLine, "┘", "┤", 1)
207		return body[:lastNewline+1] + lastLine
208	}
